      "codeSnippet": "class Apple extends RuntimeException {}\r\nclass Orange extends Exception {}\r\nclass Banana extends Error {}\r\nclass Pear extends Apple {}\r\nclass Tomato extends Orange {}\r\nclass Peach extends Throwable {}",
