      "chapterTitle": "Chapter 11: Exceptions and Localization",
      "questionNumber": 18,
      "questionText": "Kết quả đầu ra của đoạn mã sau là gì?",
      "codeSnippet": "import java.io.*;\r\npublic class FamilyCar {\r\n   static class Door implements AutoCloseable {\r\n      public void close() {\r\n         System.out.print(\"D\");\r\n   } }\r\n   static class Window implements Closeable {\r\n      public void close() {\r\n         System.out.print(\"W\");\r\n         throw new RuntimeException();\r\n   } }\r\n   public static void main(String[] args) {\r\n      var d = new Door();\r\n      try (d; var w = new Window()) {\r\n         System.out.print(\"T\");\r\n      } catch (Exception e) {\r\n         System.out.print(\"E\");\r\n      } finally {\r\n         System.out.print(\"F\");\r\n      } } }",
      "isMultipleChoice": false,
      "options": [
        {
          "key": "A",
          "text": "`TWF`"
        },
        {
          "key": "B",
          "text": "`TWDF`"
        },
        {
          "key": "C",
          "text": "`TWDEF`"
        },
        {
          "key": "D",
          "text": "`TWF` theo sau bởi một ngoại lệ"
        },
        {
          "key": "E",
          "text": "`TWDF` theo sau bởi một ngoại lệ"
        },
        {
          "key": "F",
          "text": "`TWEF` theo sau bởi một ngoại lệ"
        },
        {
          "key": "G",
          "text": "Đoạn mã không biên dịch được."
        }
      ],
